<script lang="ts">
  import { get } from 'svelte/store';
  import Icon from '$lib/components/Icon.svelte';
  import { creatorProfile, creatorProducts, storefront, updateStorefront, loadCreatorData, type StorefrontSettings } from '$lib/stores/creator';
  import { apiRequest } from '$lib/api';
  import { getSupabaseBrowserClient } from '$lib/supabase/client';
  import { showToast } from '$lib/stores/marketplace';

  let form: StorefrontSettings = { ...get(storefront), sections: { ...get(storefront).sections } };
  let formHydrated = false;
  let previewMode: 'desktop'|'mobile' = 'desktop';
  let section = 'Brand & profile';
  const sectionLinks: { label:string; icon:'user'|'grid'|'star'|'shield'|'eye' }[] = [
    {label:'Brand & profile',icon:'user'}, {label:'Homepage layout',icon:'grid'}, {label:'Featured products',icon:'star'}, {label:'Store policies',icon:'shield'}, {label:'Visibility',icon:'eye'}
  ];
  const layoutBlocks: { key:string; title:string; hint:string; icon:'home'|'star'|'chart'|'clock'|'user' }[] = [
    {key:'hero',title:'Hero and studio identity',hint:'Primary creator introduction',icon:'home'},
    {key:'featured',title:'Featured release',hint:'Highlight one strategic product',icon:'star'},
    {key:'bestsellers',title:'Bestsellers',hint:'Automatic by paid sales',icon:'chart'},
    {key:'latest',title:'Latest releases',hint:'Automatic by publish date',icon:'clock'},
    {key:'about',title:'About the studio',hint:'Your longer brand story',icon:'user'}
  ];
  const accents: StorefrontSettings['accent'][] = ['cyan','violet','magenta'];
  $: if (!formHydrated && $storefront.displayName) {
    form = { ...$storefront, sections: { ...$storefront.sections } };
    formHydrated = true;
  }
  $: featured = $creatorProducts.find((item)=>item.slug===form.featuredSlug) ?? $creatorProducts[0];
  let avatarInput:HTMLInputElement | undefined;
  let bannerInput:HTMLInputElement | undefined;
  const selectedFile=(event:Event)=>(event.currentTarget as HTMLInputElement).files?.[0];
  let mediaUploading:''|'avatar'|'banner'='';
  function save(){ updateStorefront({...form}); }
  function toggleSection(key:string){ form={...form,sections:{...form.sections,[key]:form.sections[key]===false}}; }
  async function uploadMedia(kind:'avatar'|'banner',file?:File){
    if(!file)return; mediaUploading=kind;
    try{
      const signed=await apiRequest<{path:string;token:string}>("/api/vendor/media",{method:'POST',body:JSON.stringify({kind,file:{name:file.name,size:file.size,type:file.type}})});
      const {error}=await getSupabaseBrowserClient().storage.from(kind==='avatar'?'avatars':'storefront-banners').uploadToSignedUrl(signed.path,signed.token,file,{contentType:file.type});
      if(error)throw error;
      await apiRequest('/api/vendor/media',{method:'PATCH',body:JSON.stringify({kind,path:signed.path})});
      await loadCreatorData(true); showToast(`${kind==='avatar'?'Logo':'Banner'} updated`,'success');
    }catch(error){showToast(error instanceof Error?error.message:'Image upload failed','warning');}
    finally{mediaUploading='';}
  }
</script>

<svelte:head><title>Storefront Editor — Creator Hub — AssetGuru</title></svelte:head>
<header class="page-head"><div><span class="eyebrow">Public presence</span><h1>Shape your <span class="gradient-text">storefront.</span></h1><p>Build a recognisable creator home without sacrificing marketplace clarity or buyer trust.</p></div><div class="head-actions"><a class="button button-secondary" href={$creatorProfile.slug ? `/creators/${$creatorProfile.slug}` : "/creators"}><Icon name="eye" size={17}/> View live store</a><button class="button button-primary" type="button" onclick={save}><Icon name="check" size={17}/> Save storefront</button></div></header>

<input class="hidden-file" bind:this={avatarInput} type="file" accept="image/jpeg,image/png,image/webp" onchange={(event)=>uploadMedia('avatar',selectedFile(event))}/><input class="hidden-file" bind:this={bannerInput} type="file" accept="image/jpeg,image/png,image/webp" onchange={(event)=>uploadMedia('banner',selectedFile(event))}/>

<div class="editor-layout">
  <aside class="sections glass">{#each sectionLinks as item}<button class:active={section===item.label} type="button" onclick={() => section=item.label}><Icon name={item.icon} size={17}/><span>{item.label}</span></button>{/each}<div class="profile-score"><span><b>{Math.round($creatorProfile.completion)}%</b><small>Profile complete</small></span><progress max="100" value={$creatorProfile.completion}></progress><p>{$creatorProfile.completion >= 100 ? 'Storefront complete. Stripe payouts are configured separately.' : 'Complete your identity, support and visual details to reach 100%.'}</p></div></aside>

  <main class="form-panel glass">
    {#if section==='Brand & profile'}
      <div class="panel-title"><span class="eyebrow">Identity</span><h2>Brand and profile</h2><p>This information appears on your creator store and alongside every product.</p></div><div class="media-fields"><div class="avatar-field"><img src={$creatorProfile.avatar} alt=""/><button type="button" disabled={Boolean(mediaUploading)} onclick={() => avatarInput?.click()}><Icon name="upload" size={14}/> {mediaUploading==='avatar'?'Uploading…':'Replace logo'}</button></div><div class="banner-field"><img src={$creatorProfile.banner} alt=""/><button type="button" disabled={Boolean(mediaUploading)} onclick={() => bannerInput?.click()}><Icon name="upload" size={14}/> {mediaUploading==='banner'?'Uploading…':'Replace banner'}</button><small>JPG, PNG or WebP · recommended 1800 × 520 px</small></div></div><label>Display name<input bind:value={form.displayName} maxlength="50"/></label><label>Store tagline<input bind:value={form.tagline} maxlength="120"/><small>{form.tagline.length}/120 characters</small></label><label>About your studio<textarea bind:value={form.bio} rows="7"></textarea></label><div class="two"><label>Support email<input type="email" bind:value={form.supportEmail}/></label><label>Typical response time<select bind:value={form.responseTime}><option>Within 4 hours</option><option>Within 8 hours</option><option>Within 1 business day</option><option>Within 2 business days</option></select></label></div><fieldset><legend>Store accent</legend><div class="accents">{#each accents as accent}<button class:active={form.accent===accent} data-accent={accent} type="button" onclick={() => form.accent=accent}><i></i><span>{accent}</span><Icon name="check" size={14}/></button>{/each}</div></fieldset>
    {:else if section==='Homepage layout'}
      <div class="panel-title"><span class="eyebrow">Merchandising</span><h2>Store homepage layout</h2><p>Choose the order in which buyers encounter your story and products.</p></div><div class="layout-list">{#each layoutBlocks as block,index}<article><i>{index+1}</i><Icon name={block.icon} size={18}/><span><b>{block.title}</b><small>{block.hint}</small></span><label><input type="checkbox" checked={form.sections[block.key] !== false} onchange={() => toggleSection(block.key)}/> Visible</label></article>{/each}</div><div class="layout-tip"><Icon name="spark" size={19}/><span><b>Recommended order</b><small>Put one strong featured product before the full catalogue. Buyers engage better with a clear starting point.</small></span></div>
    {:else if section==='Featured products'}
      <div class="panel-title"><span class="eyebrow">Spotlight</span><h2>Featured products</h2><p>Select the product that anchors your creator-store hero.</p></div><div class="product-choice">{#each $creatorProducts.filter((item)=>item.status==='Published') as product}<label class:selected={form.featuredSlug===product.slug}><input type="radio" bind:group={form.featuredSlug} value={product.slug}/><img src={product.image} alt=""/><span><b>{product.title}</b><small>{product.category} · £{product.price.toFixed(2)}</small></span><em>{product.sales.toLocaleString('en-GB')} sales</em></label>{/each}</div><a class="button button-secondary" href="/creator/products"><Icon name="bundle" size={17}/> Manage published products</a>
    {:else if section==='Store policies'}
      <div class="panel-title"><span class="eyebrow">Buyer expectations</span><h2>Support and store policies</h2><p>Platform terms remain authoritative; your store policy can clarify how you provide product support.</p></div><label>Support promise<textarea rows="5" bind:value={form.supportPromise} placeholder="Explain how buyers should request product support."></textarea></label><label>Update commitment<textarea rows="5" bind:value={form.updateCommitment} placeholder="Explain how you maintain compatibility and product updates."></textarea></label><label>Custom licence notes<textarea rows="4" bind:value={form.licenceNotes} placeholder="Add non-conflicting store-specific licence guidance."></textarea></label><div class="policy-note"><Icon name="shield" size={20}/><span><b>Marketplace protections stay consistent</b><small>Vendors cannot replace AssetGuru’s buyer terms, digital-content policy or core licence restrictions with conflicting wording.</small></span></div>
    {:else}
      <div class="panel-title"><span class="eyebrow">Privacy and display</span><h2>Visibility settings</h2><p>Control which performance signals and store states are public.</p></div><div class="toggle-list"><label><input type="checkbox" bind:checked={form.showSales}/><span><b>Show total store sales</b><small>Display a rounded lifetime-sales count on your public profile.</small></span></label><label><input type="checkbox" bind:checked={form.showFollowers}/><span><b>Show follower count</b><small>Build social proof around your creator audience.</small></span></label><label class="vacation"><input type="checkbox" bind:checked={form.vacationMode}/><span><b>Vacation mode</b><small>Keep products available but set buyer expectations with an extended response-time notice.</small></span></label></div><div class="public-preview"><Icon name={form.vacationMode?'alert':'check'} size={22}/><span><b>{form.vacationMode?'Vacation notice will be displayed':'Store is fully available'}</b><small>{form.vacationMode?'Support response times will be shown as temporarily extended.':'Products, follow controls and support information are visible.'}</small></span></div>
    {/if}
  </main>

  <aside class="preview-wrap">
    <div class="preview-tools glass"><span>Live preview</span><div><button class:active={previewMode==='desktop'} type="button" onclick={() => previewMode='desktop'}><Icon name="grid" size={16}/></button><button class:active={previewMode==='mobile'} type="button" onclick={() => previewMode='mobile'}><Icon name="menu" size={16}/></button></div></div>
    <div class:mobile={previewMode==='mobile'} class="preview glass" data-accent={form.accent}>
      <div class="preview-banner"><img src={$creatorProfile.banner} alt=""/></div><div class="preview-id"><img src={$creatorProfile.avatar} alt=""/><div><span>VERIFIED CREATOR</span><h2>{form.displayName || 'Creator name'}</h2><p>{form.tagline || 'Your store tagline'}</p></div><button type="button">Follow</button></div><div class="preview-stats"><span><b>{$creatorProfile.rating || '—'}</b><small>rating</small></span>{#if form.showSales}<span><b>{$creatorProducts.reduce((sum,item)=>sum+item.sales,0).toLocaleString('en-GB')}</b><small>sales</small></span>{/if}{#if form.showFollowers}<span><b>{$creatorProfile.followers.toLocaleString('en-GB')}</b><small>followers</small></span>{/if}<span><b>{$creatorProducts.filter((item)=>item.status==='Published').length}</b><small>products</small></span></div>{#if form.vacationMode}<div class="vacation-banner"><Icon name="clock" size={14}/> This creator is away. Replies may take longer.</div>{/if}{#if featured}<div class="featured"><span>FEATURED RELEASE</span><img src={featured.image} alt=""/><h3>{featured.title}</h3><p>{featured.category} · v{featured.version}</p><strong>£{featured.price.toFixed(2)}</strong></div>{/if}<div class="about"><h3>About {form.displayName}</h3><p>{form.bio}</p></div>
    </div>
  </aside>
</div>

<style>
